import{_ as e,c as t,f as n,g as r,l as i,n as a,p as o,s,w as c}from"./index-C-vzxM_u.js";import{t as l}from"./navigate-CE8fDTnR.js";var u=[{id:`iam`,num:`1`,title:`IAM & Security`},{id:`vpc`,num:`2`,title:`VPC & Networking`},{id:`ec2`,num:`3`,title:`EC2 & Auto Scaling`},{id:`lambda`,num:`4`,title:`Lambda & Serverless`},{id:`ecs`,num:`5`,title:`ECS & Containers`},{id:`s3`,num:`6`,title:`S3 & Storage`},{id:`rds`,num:`7`,title:`RDS & DynamoDB`},{id:`cicd`,num:`8`,title:`CodePipeline & DevOps`},{id:`arch`,num:`9`,title:`Architecture & Best Practices`},{id:`bastion`,num:`10`,title:`Bastion & Jump Host`}],d={name:`CloudHubPage`,data(){return{tocSections:u}},methods:{handleNav(e){l(e)},scrollTo(e){let t=document.getElementById(e);t&&t.scrollIntoView({behavior:`smooth`,block:`start`})}}},f={class:`cloud-page`,style:{"--color-accent":`#ff9900`}},p={class:`page`},m={class:`topbar`},h={class:`links`},g={class:`toc`},_=[`href`,`onClick`];function v(a,l,u,d,v,y){return r(),n(`div`,f,[i(`div`,p,[i(`div`,m,[l[1]||=i(`div`,null,[i(`h1`,null,`☁️ AWS Cloud Foundations & Core`),i(`p`,{class:`desc`},`IAM, VPC, EC2, Lambda, S3, RDS, ECS, CodePipeline — kiến trúc, code mẫu, best practices`)],-1),i(`div`,h,[i(`a`,{href:`#`,onClick:l[0]||=s(e=>y.handleNav(`/`),[`prevent`])},`Trang chủ`)])]),i(`div`,g,[(r(!0),n(t,null,e(v.tocSections,e=>(r(),n(`a`,{key:e.id,href:`#`+e.id,onClick:s(t=>y.scrollTo(e.id),[`prevent`])},c(e.num)+`. `+c(e.title),9,_))),128))]),l[2]||=o(`<div class="section" id="iam" data-v-8de29760><div class="section-title" data-v-8de29760>1. IAM (Identity &amp; Access Management)</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>IAM là gì?</h3><p data-v-8de29760>IAM là dịch vụ quản lý danh tính và quyền truy cập AWS. Mọi thao tác với AWS API đều phải qua IAM authentication + authorization. <strong data-v-8de29760>IAM không phải là service-specific</strong> — nó áp dụng cho toàn bộ tài khoản AWS.</p><h3 data-v-8de29760>IAM Components</h3><div class="grid-2" data-v-8de29760><div class="card" data-v-8de29760><h4 data-v-8de29760>👤 User</h4><p data-v-8de29760>Một người/vật thực thể. Có long-term credentials (password + access key). Khuyến nghị: 1 user = 1 người thật.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>👥 Group</h4><p data-v-8de29760>Tập hợp users. Gán policy cho group thay vì từng user. Quản lý dễ hơn, ít trùng lặp.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>🤖 Role</h4><p data-v-8de29760>Không gắn với user cụ thể. Được assume bởi users, services (EC2, Lambda), hoặc AWS accounts khác. Có temporary credentials (STS).</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>📜 Policy</h4><p data-v-8de29760>JSON document định nghĩa quyền (Allow/Deny) trên các resource. Gán vào User, Group, hoặc Role.</p></div></div><h3 data-v-8de29760>IAM Policy — cấu trúc JSON</h3><pre data-v-8de29760><code data-v-8de29760>{
  &quot;Version&quot;: &quot;2012-10-17&quot;,
  &quot;Statement&quot;: [
    {
      &quot;Effect&quot;: &quot;Allow&quot;,
      &quot;Action&quot;: [&quot;s3:GetObject&quot;, &quot;s3:PutObject&quot;],
      &quot;Resource&quot;: &quot;arn:aws:s3:::my-app-bucket/uploads/*&quot;
    }
  ]
}</code></pre><h3 data-v-8de29760>Least Privilege — nguyên tắc vàng</h3><p data-v-8de29760>Chỉ cấp quyền tối thiểu cần thiết. Dùng <strong data-v-8de29760>AWS Managed Policies</strong> khi bắt đầu, sau đó chuyển sang <strong data-v-8de29760>Customer Managed Policies</strong> chi tiết hơn.</p><h3 data-v-8de29760>IAM Best Practices</h3><ul data-v-8de29760><li data-v-8de29760><strong data-v-8de29760>Không dùng root account</strong> — tạo admin user với MFA</li><li data-v-8de29760><strong data-v-8de29760>MFA bắt buộc</strong> cho users có quyền cao</li><li data-v-8de29760><strong data-v-8de29760>Rotate access key</strong> định kỳ (90 ngày)</li><li data-v-8de29760><strong data-v-8de29760>IAM Access Analyzer</strong> — phát hiện resource được share public</li></ul></div></div><div class="section" id="vpc" data-v-8de29760><div class="section-title" data-v-8de29760>2. VPC (Virtual Private Cloud) &amp; Networking</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>VPC là gì?</h3><p data-v-8de29760>VPC là mạng ảo riêng trong AWS — <strong data-v-8de29760>logically isolated network</strong> trong tài khoản của bạn. Bạn tự định nghĩa IP range, subnets, route tables, gateways.</p><h3 data-v-8de29760>VPC Architecture cơ bản</h3><div class="diagram" data-v-8de29760> Internet → Internet Gateway (IGW) → Public Subnet → EC2<br data-v-8de29760> │<br data-v-8de29760> └→ NAT Gateway → Private Subnet → EC2/DB<br data-v-8de29760></div><h3 data-v-8de29760>CIDR &amp; Subnets</h3><pre data-v-8de29760><code data-v-8de29760>VPC CIDR: 10.0.0.0/16 (65536 địa chỉ)

Public Subnet  10.0.1.0/24  (AZ: ap-southeast-1a)
Private Subnet 10.0.3.0/24  (AZ: ap-southeast-1a)
DB Subnet      10.0.5.0/24  (AZ: ap-southeast-1a)</code></pre><h3 data-v-8de29760>Security Groups vs NACL</h3><div class="grid-2" data-v-8de29760><div class="card" data-v-8de29760><h4 data-v-8de29760>🔒 Security Group (Stateful)</h4><ul data-v-8de29760><li data-v-8de29760>Stateful — allow inbound → tự động allow outbound</li><li data-v-8de29760>Chỉ có Allow rules</li><li data-v-8de29760>Reference SG khác: sg-xxx</li></ul></div><div class="card" data-v-8de29760><h4 data-v-8de29760>📋 NACL (Stateless)</h4><ul data-v-8de29760><li data-v-8de29760>Stateless — cần define cả inbound + outbound</li><li data-v-8de29760>Có Allow + Deny rules</li><li data-v-8de29760>Reference IP/CIDR</li></ul></div></div></div></div><div class="section" id="ec2" data-v-8de29760><div class="section-title" data-v-8de29760>3. EC2 &amp; Auto Scaling</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>EC2 Instance Types &amp; Families</h3><div class="grid-3" data-v-8de29760><div class="card" data-v-8de29760><h4 data-v-8de29760>⚡ General Purpose (T3, M7g)</h4><p data-v-8de29760>Web servers, small DB, dev/test. T3 burstable.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>🔬 Compute Optimized (C7g)</h4><p data-v-8de29760>Batch processing, gaming, HPC. Graviton3 ARM, 20% rẻ hơn Intel.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>📦 Memory Optimized (R7g, X2iedn)</h4><p data-v-8de29760>In-memory caches (Redis), large DB.</p></div></div><h3 data-v-8de29760>Auto Scaling — Launch Template</h3><pre data-v-8de29760><code data-v-8de29760>aws autoscaling create-auto-scaling-group \\
  --auto-scaling-group-name prod-web-asg \\
  --launch-template LaunchTemplateName=web-v2 \\
  --min-size 2 --max-size 10 --desired-capacity 3 \\
  --availability-zones ap-southeast-1a ap-southeast-1b</code></pre><h3 data-v-8de29760>EC2 Best Practices</h3><ul data-v-8de29760><li data-v-8de29760><strong data-v-8de29760>Dùng IAM Role</strong> cho EC2 — không bao giờ nhúng access key</li><li data-v-8de29760><strong data-v-8de29760>IMDSv2 bắt buộc</strong> — set HttpTokens=required</li><li data-v-8de29760><strong data-v-8de29760>SSM Session Manager</strong> thay vì SSH</li><li data-v-8de29760><strong data-v-8de29760>Spot Instances</strong> cho workload chịu được interrupt — tiết kiệm 70-90%</li></ul></div></div><div class="section" id="lambda" data-v-8de29760><div class="section-title" data-v-8de29760>4. Lambda &amp; Serverless</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>Lambda là gì?</h3><p data-v-8de29760>Function-as-a-Service (FaaS) — chạy code không cần quản lý server. AWS quản lý infrastructure, auto-scale. <strong data-v-8de29760>Chỉ trả tiền khi code chạy</strong>.</p><h3 data-v-8de29760>Lambda với API Gateway (REST API)</h3><pre data-v-8de29760><code data-v-8de29760>export const handler = async (event) =&gt; {
  const headers = { &#39;Content-Type&#39;: &#39;application/json&#39; };
  try {
    switch (event.httpMethod) {
      case &#39;GET&#39;: {
        const { id } = event.pathParameters || {};
        const { Item } = await ddb.send(new GetCommand({ TableName: process.env.TABLE_NAME, Key: { pk: id } }));
        return { statusCode: 200, headers, body: JSON.stringify(Item) };
      }
      case &#39;POST&#39;: {
        const body = JSON.parse(event.body || &#39;{}&#39;);
        const item = { pk: crypto.randomUUID(), ...body };
        await ddb.send(new PutCommand({ TableName: process.env.TABLE_NAME, Item: item }));
        return { statusCode: 201, headers, body: JSON.stringify(item) };
      }
    }
  } catch (err) {
    return { statusCode: 500, headers, body: JSON.stringify({ error: &#39;Internal error&#39; }) };
  }
};</code></pre><h3 data-v-8de29760>Lambda Best Practices</h3><ul data-v-8de29760><li data-v-8de29760><strong data-v-8de29760>Cold Start:</strong> Java/.NET ~1-5s, Node.js/Python ~100-300ms</li><li data-v-8de29760><strong data-v-8de29760>Execution Timeout:</strong> tối đa 15 phút</li><li data-v-8de29760><strong data-v-8de29760>Stateless:</strong> không lưu state trong memory</li><li data-v-8de29760><strong data-v-8de29760>VPC Lambda:</strong> cần ENI → cold start lâu hơn</li></ul></div></div><div class="section" id="ecs" data-v-8de29760><div class="section-title" data-v-8de29760>5. ECS &amp; Container Orchestration</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>ECS là gì?</h3><p data-v-8de29760>Amazon Elastic Container Service — orchestration cho Docker containers. Có 2 launch types: <strong data-v-8de29760>Fargate</strong> (serverless) và <strong data-v-8de29760>EC2</strong> (tự quản cluster).</p><h3 data-v-8de29760>ECS vs EKS vs Lambda</h3><div class="grid-3" data-v-8de29760><div class="card" data-v-8de29760><h4 data-v-8de29760>🐳 ECS (Fargate)</h4><p data-v-8de29760>Serverless container. AWS quản lý control plane. Đơn giản nhất.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>☸️ EKS (Kubernetes)</h4><p data-v-8de29760>Managed K8s — chuẩn CNCF. Portable nhưng phức tạp hơn.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>⚡ Lambda</h4><p data-v-8de29760>FaaS — event-driven. Tối đa 15 ph execution.</p></div></div></div></div><div class="section" id="s3" data-v-8de29760><div class="section-title" data-v-8de29760>6. S3 (Simple Storage Service)</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>S3 là gì?</h3><p data-v-8de29760>S3 là object storage — lưu trữ <strong data-v-8de29760>unlimited objects</strong> (0 byte – 5 TB). <strong data-v-8de29760>99.999999999% durability</strong> (11 9&#39;s).</p><h3 data-v-8de29760>S3 Storage Classes</h3><div class="grid-2" data-v-8de29760><div class="card" data-v-8de29760><h4 data-v-8de29760>⚡ S3 Standard</h4><p data-v-8de29760>Frequent access. $0.023/GB. Cho web app, big data.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>📉 S3 Intelligent-Tiering</h4><p data-v-8de29760>Tự động di chuyển objects giữa tiers.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>❄️ S3 Glacier</h4><p data-v-8de29760>Archive — rẻ nhất $0.001/GB. Cho backup.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>🗄️ S3 One Zone-IA</h4><p data-v-8de29760>Chỉ 1 AZ, rẻ hơn Standard-IA 20%.</p></div></div><h3 data-v-8de29760>S3 Best Practices</h3><ul data-v-8de29760><li data-v-8de29760><strong data-v-8de29760>Prefix cho performance:</strong> 5500 GET/3500 PUT requests/s mỗi prefix</li><li data-v-8de29760><strong data-v-8de29760>Multipart Upload:</strong> cho file &gt;100 MB</li><li data-v-8de29760><strong data-v-8de29760>Object Lock:</strong> WORM — compliance, legal hold</li><li data-v-8de29760><strong data-v-8de29760>Replication:</strong> CRR (cross-region) cho disaster recovery</li></ul></div></div><div class="section" id="rds" data-v-8de29760><div class="section-title" data-v-8de29760>7. RDS &amp; DynamoDB</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>RDS — Relational Databases</h3><p data-v-8de29760>Managed DB: <strong data-v-8de29760>Aurora, PostgreSQL, MySQL, MariaDB, SQL Server</strong>. AWS quản lý: OS patching, backup, replication, failover.</p><h3 data-v-8de29760>RDS vs DynamoDB — chọn cái nào?</h3><div class="grid-2" data-v-8de29760><div class="card" data-v-8de29760><h4 data-v-8de29760>🗄️ RDS (SQL)</h4><ul data-v-8de29760><li data-v-8de29760>Dữ liệu có quan hệ (JOIN, FK)</li><li data-v-8de29760>Complex queries, aggregations</li><li data-v-8de29760>Ví dụ: ERP, CRM</li></ul></div><div class="card" data-v-8de29760><h4 data-v-8de29760>📊 DynamoDB (NoSQL)</h4><ul data-v-8de29760><li data-v-8de29760>Key-value access pattern, high scale</li><li data-v-8de29760>Single-digit ms ở mọi scale</li><li data-v-8de29760>Ví dụ: session, shopping cart</li></ul></div></div></div></div><div class="section" id="cicd" data-v-8de29760><div class="section-title" data-v-8de29760>8. CodePipeline &amp; DevOps</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>CI/CD trên AWS</h3><p data-v-8de29760>AWS cung cấp CI/CD stack: <strong data-v-8de29760>CodeCommit</strong> (Git), <strong data-v-8de29760>CodeBuild</strong> (build/test), <strong data-v-8de29760>CodeDeploy</strong> (deploy), <strong data-v-8de29760>CodePipeline</strong> (orchestration).</p><h3 data-v-8de29760>CI/CD Best Practices</h3><ul data-v-8de29760><li data-v-8de29760><strong data-v-8de29760>Build artifact duy nhất</strong> — build 1 lần, deploy qua các môi trường</li><li data-v-8de29760><strong data-v-8de29760>Immutable infrastructure</strong> — tạo AMI mới mỗi deploy</li><li data-v-8de29760><strong data-v-8de29760>Canary / Blue-Green</strong> — giảm blast radius</li><li data-v-8de29760><strong data-v-8de29760>Automated rollback</strong> — CloudWatch alarm + deployment circuit breaker</li></ul></div></div><div class="section" id="arch" data-v-8de29760><div class="section-title" data-v-8de29760>9. Architecture &amp; Best Practices</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>Well-Architected Framework</h3><div class="grid-2" data-v-8de29760><div class="card" data-v-8de29760><h4 data-v-8de29760>⚡ Operational Excellence</h4><p data-v-8de29760>IaC (CDK/CF), monitoring, runbooks, auto-remediation.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>🔒 Security</h4><p data-v-8de29760>Least privilege IAM, encryption, VPC isolation.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>💪 Reliability</h4><p data-v-8de29760>Multi-AZ, auto scaling, health checks.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>💰 Cost Optimization</h4><p data-v-8de29760>Savings Plans, Spot instances, auto scaling.</p></div></div></div></div><div class="section" id="bastion" data-v-8de29760><div class="section-title" data-v-8de29760>10. Bastion &amp; Jump Host</div><div class="section-body" data-v-8de29760><h3 data-v-8de29760>Bastion Host là gì?</h3><p data-v-8de29760><strong data-v-8de29760>Bastion Host</strong> là máy chủ hardened đặt ở <strong data-v-8de29760>public subnet</strong>, là <strong data-v-8de29760>cổng vào duy nhất</strong> để SSH/RDP vào các máy trong <strong data-v-8de29760>private subnet</strong>.</p><h3 data-v-8de29760>Thay thế hiện đại: SSM Session Manager</h3><p data-v-8de29760>SSH vào private instance <strong data-v-8de29760>không cần bastion, không mở port 22, không public IP</strong>. Dùng IAM thay vì SSH keys, log đầy đủ, tích hợp MFA, chi phí 0$.</p><pre data-v-8de29760><code data-v-8de29760>aws ssm start-session --target i-xxxxx</code></pre><h3 data-v-8de29760>Bastion vs NAT Gateway</h3><div class="grid-2" data-v-8de29760><div class="card" data-v-8de29760><h4 data-v-8de29760>🛡️ Bastion Host</h4><p data-v-8de29760><strong data-v-8de29760>Inbound</strong> — cho người từ ngoài SSH vào private subnet.</p></div><div class="card" data-v-8de29760><h4 data-v-8de29760>🌐 NAT Gateway</h4><p data-v-8de29760><strong data-v-8de29760>Outbound</strong> — cho private instances đi ra internet.</p></div></div></div></div>`,10)])])}var y=a(d,[[`render`,v],[`__scopeId`,`data-v-8de29760`]]);export{y as default};